frappe.ui.form.on('Developer', {
    get_current_location(frm) {

        if (!navigator.geolocation) {
            frappe.msgprint(__('Geolocation is not supported by your browser.'));
            return;
        }

        frappe.show_alert({
            message: __('Fetching GPS Coordinates...'),
            indicator: 'orange'
        }, 3);

        navigator.geolocation.getCurrentPosition(
            function (position) {

                const lat = position.coords.latitude;
                const lng = position.coords.longitude;

                const geojson = {
                    type: "FeatureCollection",
                    features: [{
                        type: "Feature",
                        properties: { point_type: "marker" },
                        geometry: {
                            type: "Point",
                            coordinates: [lng, lat]
                        }
                    }]
                };

                // Set GeoJSON value
                frm.set_value('location', JSON.stringify(geojson));

                // 🔥 AUTO-CENTER MAP
                frm.refresh_field('location');

                // Force map to re-render & center
                setTimeout(() => {
                    if (frm.fields_dict.location?.map) {
                        frm.fields_dict.location.map.fitBounds();
                    }
                }, 300);

                frappe.show_alert({
                    message: __('📍 Location Fetched'),
                    indicator: 'green'
                }, 4);
            },
            function (error) {
                console.error(error);

                frappe.show_alert({
                    message: __('❌ Location Not Found: Try Again ') + error.message,
                    indicator: 'red'
                }, 5);
            },
            {
                enableHighAccuracy: true,
                timeout: 10000
            }
        );
    }
});

