frappe.ui.form.on('Site Visit', {
    
    // Triggered when "Send OTP" button is clicked
    btn_send_otp: function(frm) {
        
        // Validation: Ensure a Lead is selected
        if (!frm.doc.lead) {
            frappe.msgprint(__('Please select a Lead first.'));
            return;
        }

        frappe.show_alert({message: __('Sending OTP...'), indicator: 'orange'});

        // Call the backend function 'trigger_otp'
        frappe.call({
            method: 'trigger_otp',
            doc: frm.doc, // Sends the current document context
            freeze: true, // Blocks the screen while loading
            callback: function(r) {
                // The Python code returns the string "success" or "failed"
                if (r.message === "success") {
                    
                    // Clear the input field so they can type the new OTP
                    frm.set_value('otp_input', '');
                    
                    // Note: Your Python code already has a frappe.msgprint showing the OTP
                    // So we don't need to show another alert here.
                    frappe.show_alert({message: __('OTP Sent Successfully'), indicator: 'green'});

                } else {
                    frappe.msgprint({
                        title: __('Failed'),
                        message: __('Could not send OTP. Please check the Error Log.'),
                        indicator: 'red'
                    });
                }
            }
        });
    },

    // Triggered when "Verify OTP" button is clicked
    btn_verify_otp: function(frm) {
        
        // Validation: Ensure the user typed something
        if (!frm.doc.otp_input) {
            frappe.msgprint(__('Please enter the OTP in the input field.'));
            return;
        }

        frappe.call({
            method: 'verify_client_otp',
            doc: frm.doc,
            args: {
                // Pass the value from the 'otp_input' field to the python function
                user_otp: frm.doc.otp_input
            },
            freeze: true,
            callback: function(r) {
                // The Python code returns True or False
                if (r.message === true) {
                    
                    // 1. Check the "Is Verified" box
                    frm.set_value('is_verified', 1);
                    
                    // 2. Show success message
                    frappe.msgprint({
                        title: __('Success'),
                        message: __('Client Verified Successfully!'),
                        indicator: 'green'
                    });

                    // 3. Save the form to persist the verification
                    frm.save();

                } else {
                    // Show error message
                    frappe.msgprint({
                        title: __('Verification Failed'),
                        message: __('Invalid OTP. Please try again.'),
                        indicator: 'red'
                    });
                    
                    // Uncheck verification just in case
                    frm.set_value('is_verified', 0);
                }
            }
        });
    }
});

frappe.ui.form.on('Lead', {
    refresh: function(frm) {
        // Make "Is Verified" read-only
        frm.set_df_property('custom_is_verified', 'read_only', 1);
    },

    // Triggered when "Send OTP" button is clicked
    custom_send_otp: function(frm) {
        
        // 1. Validation
        if (!frm.doc.mobile_no) {
            frappe.msgprint({
                title: __('Missing Info'),
                message: __('Please enter a Mobile Number first.'),
                indicator: 'red'
            });
            return;
        }

        // 2. Call API directly (NO AUTO-SAVE)
        // We pass 'null' for lead_name if the form is new, so backend uses mobile_no as key
        frappe.call({
            method: 'homesol_app.api.trigger_otp_lead', 
            args: {
                lead_name: frm.is_new() ? null : frm.doc.name,     
                mobile_no: frm.doc.mobile_no 
            },
            freeze: true,
            callback: function(r) {
                if (r.message === "success") {
                    // Clear the OTP input field
                    frm.set_value('custom_enter_otp', '');
                    
                    frappe.msgprint({
                        title: __('OTP Sent'),
                        message: __('OTP sent to ') + frm.doc.mobile_no,
                        indicator: 'green'
                    });
                } else {
                    frappe.msgprint({
                        title: __('Failed'),
                        message: __('Could not send OTP. Please try again.'),
                        indicator: 'red'
                    });
                }
            }
        });
    },

    // Triggered when "Verify OTP" button is clicked
    custom_verify_otp: function(frm) {
        
        if (!frm.doc.custom_enter_otp) {
            frappe.msgprint(__('Please enter the OTP.'));
            return;
        }

        frappe.call({
            method: 'homesol_app.api.verify_otp_lead',
            args: {
                lead_name: frm.is_new() ? null : frm.doc.name,
                mobile_no: frm.doc.mobile_no,
                user_otp: frm.doc.custom_enter_otp
            },
            freeze: true,
            callback: function(r) {
                if (r.message === true) {
                    
                    // --- SUCCESS LOGIC ---
                    
                    // 1. Check the verified box
                    frm.set_value('custom_is_verified', 1);
                    
                    // 2. Show Success Message
                    frappe.msgprint({
                        title: __('Success'),
                        message: __('Verified! Saving Lead details now...'),
                        indicator: 'green'
                    });

                    // 3. AUTO-SAVE NOW (Only after verification)
                    frm.save();

                } else {
                    frappe.msgprint({
                        title: __('Verification Failed'),
                        message: __('Invalid OTP. Please try again.'),
                        indicator: 'red'
                    });
                    frm.set_value('custom_is_verified', 0);
                }
            }
        });
    }
});
